function normalizeChannelUrl(v,platform){let x=String(v||'').trim();if(!x)return '';if(!/^https?:\/\//i.test(x))x='https://'+x;try{const u=new URL(x),h=u.hostname.toLowerCase().replace(/^www\./,'');if(platform==='tiktok'&&h!=='tiktok.com')return '';if(platform==='youtube'&&!['youtube.com','m.youtube.com','youtu.be'].includes(h))return '';return u.toString()}catch{return ''}}
