function renderTenantSellerAnalytics(data,month){const a=data||{},summary=a.summary||{},sellers=a.sellers||[],daily=a.byDay||[],orders=a.orders||[];const put=(id,v)=>{const el=$('#'+id);if(el)el.textContent=v};put('tenantSellerMonthLabel',month?('Tháng '+month):'Khoảng thời gian');put('tenantSellerOrders',Number(summary.orders||0).toLocaleString('vi-VN'));put('tenantSellerGross',money(summary.referredGrossVnd));put('tenantSellerCommission',money(summary.commissionVnd));put('tenantSellerCount',Number(summary.sellerCount||sellers.length||0).toLocaleString('vi-VN'));const sellerRoot=$('#tenantSellerRows');if(sellerRoot)sellerRoot.innerHTML=sellers.map(v=>`<tr><td><b>${esc(v.login_id||v.display_name||'Seller')}</b><small style="display:block;overflow-wrap:anywhere">${esc(v.seller_id||'')}</small><small>${esc(v.email||'')}</small></td><td>${Number(v.orders||0).toLocaleString('vi-VN')}</td><td>${money(v.referredGrossVnd)}</td><td><b>${money(v.commissionVnd)}</b></td><td>${Number(v.commissionRate||0).toLocaleString('vi-VN',{maximumFractionDigits:2})}%</td></tr>`).join('')||'<tr><td colspan="5">Chưa có đơn hàng có Seller ID trong tháng này.</td></tr>';const dailyRoot=$('#tenantSellerDaily');if(dailyRoot){const max=Math.max(1,...daily.map(v=>Number(v.commissionVnd||0)));dailyRoot.innerHTML=daily.length?daily.map(v=>`<div class="seller-daily-row"><span>${esc(v.day)}</span><div class="seller-daily-track"><i style="width:${Math.max(0,Math.min(100,Number(v.commissionVnd||0)/max*100))}%"></i></div><b>${money(v.commissionVnd)}</b><small>${Number(v.orders||0)} đơn</small></div>`).join(''):'<p class="muted">Chưa phát sinh hoa hồng Seller.</p>'}const orderRoot=$('#tenantSellerOrdersRows');if(orderRoot)orderRoot.innerHTML=orders.map(v=>`<tr><td>${esc(formatVN(v.created_at))}<small style="display:block;overflow-wrap:anywhere">${esc(v.id)}</small></td><td>${esc(v.title||v.product_id||'File')}</td><td>${esc(v.seller_id||'—')}<small style="display:block">${esc(v.login_id||v.display_name||'')}</small></td><td>${money(v.amount_vnd)}</td><td><b>${money(v.seller_commission_vnd)}</b></td></tr>`).join('')||'<tr><td colspan="5">Chưa có đơn Seller giới thiệu.</td></tr>'}
function renderSales(s){const root=$('#salesSummary'),detail=$('#salesDetail');const today=dateVN(0),todayRow=(s.byDay||[]).find(x=>String(x.day)===today)||{};const productDaily=$('#tenantProductDailyRows');if(productDaily)productDaily.innerHTML=(s.byProductDay||[]).map(v=>`<tr><td>${esc(v.day)}</td><td>${esc(v.title||v.productId||'File')}<small style="display:block;overflow-wrap:anywhere">${esc(v.productId||'')}</small></td><td>${Number(v.orders||0).toLocaleString('vi-VN')}</td><td><b>${money(v.revenueVnd)}</b></td></tr>`).join('')||'<tr><td colspan="4">Chưa có đơn mua file trả phí trong tháng này.</td></tr>';if(root)root.innerHTML=`<div><small>Đơn đã trả (30 ngày)</small><b>${Number(s.orders||0).toLocaleString('vi-VN')}</b></div><div><small>Doanh thu gộp (30 ngày)</small><b>${Number(s.revenueVnd||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Đơn hôm nay</small><b>${Number(todayRow.orders||0).toLocaleString('vi-VN')}</b></div><div><small>Doanh thu hôm nay</small><b>${Number(todayRow.revenue||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Tỷ lệ mua / view file</small><b>${Number(s.conversionRate||0).toLocaleString('vi-VN')}%</b></div><div><small>Thực nhận từ bán file (30 ngày)</small><b>${Number(s.sellerNetVnd||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Phí nền tảng (30 ngày)</small><b>${Number(s.commissionVnd||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Ads đã xác nhận (30 ngày)</small><b>${Number(s.adsRevenueVnd||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Tổng thực nhận file + Ads</small><b>${Number(s.totalIncomeVnd||s.revenueVnd||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Thực nhận hôm nay</small><b>${Number(todayRow.sellerNet||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Ads hôm nay</small><b>${Number(todayRow.adRevenue||0).toLocaleString('vi-VN')} ₫</b></div><div><small>Phí nền tảng hôm nay</small><b>${Number(todayRow.commission||0).toLocaleString('vi-VN')} ₫</b></div>`;if(detail){const rows=(s.byDay||[]).slice(-10);detail.innerHTML=rows.length?rows.map(x=>`<div class="file-view-row"><div><b>${esc(x.day)}</b><small>${Number(x.orders||0)} đơn${Number(x.walletOrders||0)?` · ${Number(x.walletOrders)} đơn qua ví`:''} · Ads ${Number(x.adRevenue||0).toLocaleString('vi-VN')}đ</small></div><strong>${Number(x.totalIncome??x.revenue??0).toLocaleString('vi-VN')} ₫</strong></div>`).join(''):'Chưa có giao dịch trả phí trong khoảng thời gian này.'}}
async function loadStats(){try{const selectedMonth=$('#statsMonth')?.value||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit'}).format(new Date()).slice(0,7);const x=await req('/api/tenant/stats?month='+encodeURIComponent(selectedMonth));const rows=x.rows||[],today=x.today||0;const todayStr=dateVN(0),monthFrom=selectedMonth+'-01';const v7=rows.filter(r=>r.kind==='visit').reduce((a,r)=>a+Number(r.views||0),0),v30=rows.reduce((a,r)=>a+Number(r.views||0),0);const kinds=x.viewKinds||{};[['tenantViewVisitCount',kinds.visit],['tenantViewProductCount',kinds.product],['tenantViewOutboundCount',kinds.outbound]].forEach(([id,v])=>{const el=$('#'+id);if(el)el.textContent=Number(v||0).toLocaleString('vi-VN')});$('#today').textContent=today;$('#weekViews').textContent=v7;$('#sumToday').textContent=today;$('#sum7').textContent=v7;$('#sum30').textContent=v30;chart(rows,31);$('#fileStats').innerHTML=(x.products||[]).sort((a,b)=>Number(b.views||0)-Number(a.views||0)).slice(0,20).map(p=>`<div class="file-view-row"><div><b>${esc(p.title)}</b><small>${esc(p.game||'')}</small></div><strong>${Number(p.views||0)} click/view</strong></div>`).join('')||'<p class="muted">Chưa có dữ liệu.</p>';const productBox=$('#productPerformance');if(productBox){const perf=x.productPerformance||[],pv=perf.reduce((a,p)=>a+Number(p.views||0),0),out=perf.reduce((a,p)=>a+Number(p.outboundClicks||0),0),orders=perf.reduce((a,p)=>a+Number(p.orders||0),0),revenue=perf.reduce((a,p)=>a+Number(p.revenueVnd||0),0),rate=pv?orders/pv*100:0;const kpis=`<div class="analytics-detail-grid"><div class="analytics-detail-card"><small>Tổng view file</small><h3>${pv.toLocaleString('vi-VN')}</h3></div><div class="analytics-detail-card"><small>Lượt click vượt link / tải</small><h3>${out.toLocaleString('vi-VN')}</h3></div><div class="analytics-detail-card"><small>Đơn hàng đã thanh toán</small><h3>${orders.toLocaleString('vi-VN')}</h3></div><div class="analytics-detail-card"><small>Doanh thu từ file</small><h3>${money(revenue)}</h3></div><div class="analytics-detail-card"><small>Tỷ lệ mua / view file</small><h3>${rate.toLocaleString('vi-VN',{maximumFractionDigits:2})}%</h3></div><div class="analytics-detail-card"><small>File có doanh thu cao nhất</small><h3>${esc(perf[0]?.title||'Chưa có')}</h3></div></div>`;productBox.innerHTML=perf.length?kpis+`<div class="table-wrap"><table class="analytics-detail-table"><thead><tr><th>File</th><th>View</th><th>Click tải</th><th>Đơn đã trả</th><th>Doanh thu</th><th>Tỷ lệ mua</th></tr></thead><tbody>${perf.map(p=>`<tr><td>${esc(p.title)}</td><td>${Number(p.views||0).toLocaleString('vi-VN')}</td><td>${Number(p.outboundClicks||0).toLocaleString('vi-VN')}</td><td>${Number(p.orders||0).toLocaleString('vi-VN')}</td><td>${money(p.revenueVnd||0)}</td><td>${Number(p.conversionRate||0).toLocaleString('vi-VN',{maximumFractionDigits:2})}%</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Chưa có dữ liệu hiệu quả theo file trong khoảng thời gian này.</p>'; }const refBox=$('#referrerStats');if(refBox)refBox.innerHTML=(x.referrers||[]).map(v=>`<div class="file-view-row"><div><b>${esc(v.domain)}</b></div><strong>${Number(v.views||0)} lượt</strong></div>`).join('')||'<p class="muted">Chưa ghi nhận tên miền giới thiệu bên ngoài. Một số trình duyệt có thể ẩn nguồn truy cập.</p>';if($('#freeClickCount'))$('#freeClickCount').textContent=rows.filter(r=>r.kind==='visit'&&r.day>=monthFrom).reduce((a,r)=>a+Number(r.views||0),0).toLocaleString('vi-VN');renderSales(x.sales||{});renderTenantSellerAnalytics(x.sellerAnalytics||{},selectedMonth);await loadMonth() }catch(e){console.error(e);$('#tenantChart').innerHTML='<p class="muted">Không tải được dữ liệu phân tích.</p>'}}
async function loadMonth(){const month=$('#statsMonth').value;if(!month)return;try{const x=await req('/api/tenant/stats?month='+encodeURIComponent(month));const rows=x.rows||[];const total=rows.reduce((a,r)=>a+Number(r.views||0),0),daily={};for(const r of rows)daily[r.day]=(daily[r.day]||0)+Number(r.views||0);const days=Object.entries(daily).sort((a,b)=>a[0].localeCompare(b[0]));const sales=(x.sales?.byDay||[]),paidIds=new Set((x.products||[]).filter(p=>['paid','both'].includes(String(p.product_mode||'').toLowerCase())||Number(p.sale_enabled)===1).map(p=>String(p.id))),paidDaily={};for(const r of rows){if(r.kind==='product'&&paidIds.has(String(r.product_id)))paidDaily[r.day]=(paidDaily[r.day]||0)+Number(r.views||0)}const paidDays=Object.entries(paidDaily).sort((a,b)=>a[0].localeCompare(b[0]));$('#monthSummary').innerHTML=`<b>${total.toLocaleString('vi-VN')} view</b> trong ${month} · ${days.length?`có ${days.length} ngày có dữ liệu.`:'chưa có dữ liệu.'}<div class="monthly-view-list">${days.map(([d,v])=>`<div class="file-view-row"><b>${esc(d)}</b><strong>${v.toLocaleString('vi-VN')} view</strong></div>`).join('')}</div><h4>View file trả phí theo ngày</h4><div class="monthly-view-list">${paidDays.map(([d,v])=>`<div class="file-view-row"><b>${esc(d)}</b><strong>${v.toLocaleString('vi-VN')} view</strong></div>`).join('')||'<p class="muted">Chưa có view file trả phí trong tháng này.</p>'}</div><h4>Đơn mua theo ngày</h4><div class="monthly-view-list">${sales.map(v=>`<div class="file-view-row"><div><b>${esc(v.day)}</b><small>${Number(v.orders||0)} đơn · Ads đã xác nhận ${money(v.adRevenue||0)}</small></div><strong>${money(v.totalIncome??v.revenue??0)} tổng thực nhận</strong></div>`).join('')||'<p class="muted">Chưa có đơn trả phí trong tháng.</p>'}</div><h4>Hoa hồng Seller theo ngày</h4><div class="monthly-view-list">${(x.sellerAnalytics?.byDay||[]).map(v=>`<div class="file-view-row"><div><b>${esc(v.day)}</b><small>${Number(v.orders||0)} đơn qua Seller</small></div><strong>${money(v.commissionVnd||0)} hoa hồng</strong></div>`).join('')||'<p class="muted">Chưa có hoa hồng Seller trong tháng.</p>'}</div><h4>Báo lỗi của khách trong tháng</h4><div class="monthly-view-list">${(x.supportReports||[]).map(v=>`<div class="file-view-row"><div><b>${esc(v.category||'Lỗi')}</b><small>${esc(formatVN(v.created_at))} · ${esc(v.page||'')}</small><p>${esc(v.message||'')}</p></div><strong>${esc(v.status||'open')}</strong></div>`).join('')||'<p class="muted">Chưa có báo lỗi gắn với Studio trong tháng này.</p>'}</div>`;}catch(e){$('#monthSummary').textContent='Không tải được tháng này.'}}
