async function loadWallet(){try{const x=await req('/api/tenant/wallet');$('#walletBalance').textContent=money(x.balanceVnd);$('#walletSales').textContent=money(x.totalSalesVnd);if($('#availableWithdraw'))$('#availableWithdraw').textContent='Ví: '+money(x.balanceVnd);if(x.profile){const f=$('#payoutProfile');for(const k of ['method','bank_name','account_number','account_holder','wallet_provider'])if(f.elements[k])f.elements[k].value=x.profile[k]||'';}$('#walletHistory').innerHTML='<h3>Lịch sử số dư</h3>'+(x.ledger||[]).slice(0,12).map(v=>`<div class="tenant-row"><div class="row-main"><b>${esc(v.kind)}</b><small>${esc(v.note||v.ref_id||'')} · ${esc(formatVN(v.created_at))}</small></div><strong>${Number(v.amount_vnd)>0?'+':''}${money(v.amount_vnd)}</strong></div>`).join('')||'<p class="muted">Chưa có giao dịch.</p>';$('#withdrawHistory').innerHTML='<h3>Yêu cầu rút gần đây · '+(x.withdrawals||[]).length+' lần</h3>'+(x.withdrawals||[]).map(v=>`<div class="tenant-row"><div class="row-main"><b>${money(v.payout_vnd)} · ${esc(v.status)}</b><small>Mã lệnh: <code>${esc(v.id)}</code></small><small>${esc(v.speed==='priority'?'Ưu tiên 24h':'Thông thường 7–10 ngày')} · Tạo: ${esc(formatVN(v.created_at))}</small><small>Yêu cầu ${money(v.gross_vnd)} · phí ${money(v.fee_vnd)} · thực nhận ${money(v.payout_vnd)}</small>${v.reviewed_at?`<small>Đã duyệt/cập nhật: ${esc(formatVN(v.reviewed_at))}</small>`:''}${v.paid_at?`<small>Đánh dấu đã chuyển: ${esc(formatVN(v.paid_at))}</small>`:''}${v.admin_note?`<small>Ghi chú Admin: ${esc(v.admin_note)}</small>`:''}<button class="table-btn" onclick="navigator.clipboard.writeText('${esc(v.id)}')">Copy mã lệnh</button></div></div>`).join('')||'<p class="muted">Chưa có yêu cầu rút.</p>';const cr=await req('/api/tenant/card-withdrawals');if(['paid','rejected'].includes(cr.redemptions?.[0]?.status))sessionStorage.removeItem('TEO_TENANT_CARD_WITHDRAW_KEY');$('#tenantCardWithdrawHistory').innerHTML='<h3>Lịch sử đổi thẻ</h3>'+(cr.redemptions||[]).map(v=>`<div class="tenant-row"><div class="row-main"><b>${esc(v.telco)} · ${money(v.faceVnd)} · ${esc(({pending:'Chờ Admin duyệt',approved:'Đã duyệt · chờ gửi thẻ',paid:'Đã gửi thẻ',rejected:'Đã từ chối'}[v.status]||v.status))}</b><small>Đã giữ ${money(v.debitVnd)} · ${esc(formatVN(v.createdAt))}</small>${v.cards?.length?v.cards.map(c=>`<small>Mã: <code>${esc(c.code)}</code> · Serial: <code>${esc(c.serial||'—')}</code></small>`).join(''):''}${v.adminNote?`<small>Ghi chú Admin: ${esc(v.adminNote)}</small>`:''}${v.error?`<small>${esc(v.error)}</small>`:''}</div></div>`).join('')||'<p class="muted">Chưa có giao dịch đổi thẻ.</p>';}catch(e){$('#walletHistory').textContent='Không tải được ví: '+e.message}}
