 box.innerHTML=`<div class="admin-card free-gate-card"><span class="eyebrow">GÓI FREE · THƯỞNG THÊM THỜI HẠN</span><h1>Mở Admin Free</h1><p>Mỗi chu kỳ gồm hai bước <b>BumX → Link4M</b>. Hoàn tất một chu kỳ, bạn nhận thêm <b>7 ngày Free</b>. Tối đa 2 chu kỳ trong 24 giờ.</p><div class="free-gate-progress"><b>${progress}/2 bước của chu kỳ hiện tại</b><div class="free-gate-track"><i style="width:${progress*50}%"></i></div><small>${progress===0?'Bước tiếp theo: BumX':'Đã hoàn tất BumX · Bước tiếp theo: Link4M'}</small></div><p class="muted small"><b>${quota.used}/2 chu kỳ</b> đã hoàn tất trong 24 giờ gần nhất.</p>${message?`<p class="alert-box">${esc(message)}</p>`:''}<p id="freeGateMsg" class="muted small">${esc(description)}${configured?'':' '+startHint}</p><button id="freeGateStart" class="btn primary full" ${configured&&!locked?'':'disabled'}>🔗 ${progress===0?'Tiếp tục với BumX':'Tiếp tục với Link4M'}</button>${locked?`<p class="muted small">Bạn có thể bắt đầu lại sau ${esc(quota.date)}.</p>`:''}<div class="free-gate-redeem"><label for="freeGateKey">Mã Free của bạn</label><input id="freeGateKey" type="text" inputmode="text" autocomplete="one-time-code" autocapitalize="characters" spellcheck="false" maxlength="24" placeholder="TEO-…"><button id="freeGateRedeem" type="button" class="btn primary full">🔓 ${progress===0?'Xác nhận mã BumX':'Xác nhận mã Link4M'}</button><p id="freeGateRedeemResult" class="muted small" role="status" aria-live="polite"></p></div><p class="muted small">Mã được cấp riêng cho Studio của bạn, chỉ dùng một lần và có hiệu lực trong 5 phút.</p><a class="btn ghost full" style="margin-top:10px" href="/rent.html">Quay lại trang thuê / gia hạn</a><button id="freeGateLogout" class="btn ghost full" style="margin-top:10px">Đăng xuất</button></div>`;
 document.body.appendChild(box);
 $('#freeGateStart').onclick=async()=>{const b=$('#freeGateStart'),m=$('#freeGateMsg'),clientProof=makeFreeBypassProof(),target=tenant.slug||slug;b.disabled=true;m.textContent='Đang chuẩn bị liên kết…';try{persistFreeBypassProof(target,clientProof);const r=await fetch(api('/api/rental/free/bypass/start'),{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+token,'x-tenant-slug':target},body:JSON.stringify({id:target,clientProof}),cache:'no-store'}),x=await r.json();if(!r.ok)throw Error(x.message||x.error||'Không thể tạo liên kết');if(!x.redirectUrl)throw Error('Không thể tạo liên kết.');location.href=x.redirectUrl}catch(e){clearFreeBypassProof(target);m.textContent=friendlyFreeBypassError(e);b.disabled=false}};
 $('#freeGateRedeem').onclick=async()=>{const b=$('#freeGateRedeem'),m=$('#freeGateRedeemResult'),keyText=$('#freeGateKey').value.trim().toUpperCase();if(!keyText)return m.textContent='Hãy nhập mã Free trước.';b.disabled=true;m.textContent='Đang xác nhận mã…';try{const r=await fetch(api('/api/rental/free/bypass/redeem'),{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+token,'x-tenant-slug':tenant.slug||slug},body:JSON.stringify({key:keyText}),cache:'no-store'}),x=await r.json();if(!r.ok)throw Error(x.message||x.error||'Không nhận được mã');$('#freeGateKey').value='';m.textContent=x.message||'Đã ghi nhận.';if(x.complete){document.querySelector('#freeBypassGate')?.remove();await load();initTenantTelegramLink();return;}tenant.freeBypassCount=1;tenant.freeBypassLastAt=Date.now();showFreeBypassGate({tenant,bypassProviders:providers},x.message||'Đã ghi nhận bước đầu tiên. Tiếp tục Link4M.')}catch(e){m.textContent=friendlyFreeBypassError(e);b.disabled=false}};
 $('#freeGateLogout').onclick=()=>{saveTenantSession('');localStorage.removeItem('TEO_TENANT_ID');location.href='/rent.html'};
