 root.insertBefore(panel,root.firstChild);
 $('#freeEarnStart').onclick=async()=>{const b=$('#freeEarnStart'),m=$('#freeEarnStatus'),clientProof=makeFreeBypassProof();b.disabled=true;m.textContent='Đang tạo link vượt...';try{persistFreeBypassProof(me.slug||slug,clientProof);const r=await fetch(api('/api/rental/free/bypass/start'),{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+token,'x-tenant-slug':me.slug||slug},body:JSON.stringify({id:me.slug||slug,clientProof})}),x=await r.json();if(!r.ok)throw Error(x.message||x.error||'Không thể tạo link vượt');if(!x.redirectUrl)throw Error('API chưa trả về link rút gọn.');location.href=x.redirectUrl}catch(e){clearFreeBypassProof(me.slug||slug);m.textContent=friendlyFreeBypassError(e);b.disabled=false}};
 $('#freeEarnRedeem').onclick=async()=>{const b=$('#freeEarnRedeem'),m=$('#freeEarnRedeemResult'),keyText=$('#freeEarnKey').value.trim().toUpperCase();if(!keyText)return m.textContent='Hãy dán key trước.';b.disabled=true;m.textContent='Đang xác minh key...';try{const r=await fetch(api('/api/rental/free/bypass/redeem'),{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+token,'x-tenant-slug':me.slug||slug},body:JSON.stringify({key:keyText})}),x=await r.json();if(!r.ok)throw Error(x.message||x.error||'Không nhận key được');$('#freeEarnKey').value='';const current=await req('/api/tenant/me');me=current.tenant;renderFreeBypassEarnPanel(x.message||'Đã ghi nhận.');}catch(e){m.textContent=e.message;b.disabled=false}};
