function tenantHasTimeLeftClient(v){const d=Date.parse(String(v||'').replace(' ','T')+'Z');return Number.isFinite(d)&&d>Date.now()}
async function load(){
  // Authenticate first. Optional panels are loaded independently so one failed API
  // (for example statistics or tags) cannot bounce a valid tenant back to login.
  const x=await req('/api/tenant/me');
  me=x.tenant;accountAuth=x.accountAuth||{mode:'tenant',email:me?.email||'',loginId:me?.slug||''};
  if(!me)throw new Error('Máy chủ chưa trả thông tin tài khoản thuê.');

  $('#loginBox').classList.add('hidden');
  $('#app').classList.remove('hidden');
  const dashboardMsg=$('#dashboardMsg');
  if(dashboardMsg){dashboardMsg.classList.add('hidden');dashboardMsg.textContent='';}
  $('#planBadge').textContent=me.planType==='free'?'Free · Share cơ bản':'VIP · Bán file và ví/rút tiền';
  applyPlanUI();
  renderFreeBypassEarnPanel();
  $('#fixedId').textContent=me.slug||'-';
  $('#shareLink').href='/share?tenant='+encodeURIComponent(me.slug||slug);
  $('#brandName').textContent=x.settings?.siteName||'Lại Húp File';
  $('#title').textContent=x.settings?.heroTitle||x.settings?.siteName||'Quản lý Share File';
  $('#status').textContent=me.status==='active'?'Đang thuê':me.status==='expired_grace'?'⚠ Cần gia hạn':'Hết hạn';
  expiryWarning();countdown();fillSettings(x.settings||{});monthOptions();fillTenantAccountInfo();

  const results=await Promise.allSettled([
    req('/api/tenant/products'),
    req('/api/tenant/comments'),
    req('/api/tenant/tags'),
    req('/api/tenant/notes')
  ]);
  // If any endpoint says the session itself is invalid, return to the login gate.
  const authFailure=results.find(v=>v.status==='rejected'&&['TENANT_REQUIRED','TENANT_EXPIRED','TENANT_LOCKED'].includes(v.reason?.data?.error));
  if(authFailure||!token||!readTenantSession()){
    $('#app').classList.add('hidden');$('#loginBox').classList.remove('hidden');showSecurityGate();
    throw (authFailure?.reason||new Error('Phiên thuê đã hết hạn. Hãy đăng nhập lại.'));
  }

  const failures=[];
  if(results[0].status==='fulfilled')allFiles=results[0].value.products||[];
  else {allFiles=[];failures.push('file: '+(results[0].reason?.message||'không tải được'));}
  if(results[1].status==='fulfilled')allComments=results[1].value.comments||[];
  else {allComments=[];failures.push('bình luận: '+(results[1].reason?.message||'không tải được'));}
  if(results[2].status==='fulfilled')allTags=results[2].value.tags||[];
  else {allTags=[];failures.push('tag: '+(results[2].reason?.message||'không tải được'));}
  if(results[3]?.status==='fulfilled')allNotes=results[3].value.notes||[];
  else {allNotes=[];if(results[3]?.status==='rejected')failures.push('Note: '+(results[3].reason?.message||'không tải được'));}
  $('#count').textContent=allFiles.length;
  $('#commentCount').textContent=allComments.length;
  renderFiles();renderComments();renderTags();renderTenantNotes();renderProductNoteOptions();
  if(dashboardMsg&&failures.length){dashboardMsg.textContent='Một số dữ liệu chưa tải được ('+failures.join(' · ')+'). Các mục còn lại vẫn dùng được; thử nút Làm mới sau.';dashboardMsg.classList.remove('hidden');}
  await loadStats();await loadAudit();await Promise.allSettled([loadSecurityBlocks(),loadTenantNotifications(),loadTenantSupportReports()]);
  if(me.planType!=='free')await loadWallet();
  else {const b=$('#availableWithdraw');if(b)b.textContent='—';}
}
function fillTenantAccountInfo(){const email=$('#tenantAccountEmailCurrent'),label=$('#tenantAccountAuthLabel');if(email)email.textContent=accountAuth.email||me?.email||'Chưa có email';if(label)label.textContent=accountAuth.mode==='buyer'?'Đang dùng tài khoản TeoStudio chung (SSO). Đổi email/mật khẩu sẽ đồng bộ với tài khoản và các Studio liên kết.':'Tài khoản thuê cũ dùng ID riêng. Email cần được xác minh; mật khẩu thuê được quản lý riêng.';const id=$('#tenantAccountId');if(id)id.textContent=accountAuth.loginId||me?.slug||'-';}
