async function loadSecurityBlocks(){const root=$('#tenantSecurityBlocks');if(!root)return;try{const x=await req('/api/tenant/security/blocks');root.innerHTML=(x.blocks||[]).map(b=>`<tr><td>${b.kind==='ip'?'IP':'Email'}</td><td>${esc(b.value_normalized)}</td><td>${esc(b.reason||'')}</td><td>${esc(formatVN(b.created_at))}</td><td><button class="table-btn danger" data-tenant-unblock="${esc(b.id)}">Gỡ chặn</button></td></tr>`).join('')||'<tr><td colspan="5">Chưa có mục bị chặn.</td></tr>';root.querySelectorAll('[data-tenant-unblock]').forEach(btn=>btn.onclick=async()=>{if(!confirm('Gỡ mục chặn này?'))return;try{await req('/api/tenant/security/blocks/'+encodeURIComponent(btn.dataset.tenantUnblock),{method:'DELETE'});await loadSecurityBlocks()}catch(e){alert(e.message)}})}catch(e){root.innerHTML=`<tr><td colspan="5">Không tải được danh sách: ${esc(e.message)}</td></tr>`}}
