$('#membershipPlanForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),payload={name:f.get('name'),description:f.get('description'),priceVnd:Number(f.get('priceVnd')),durationDays:Number(f.get('durationDays'))};const btn=e.currentTarget.querySelector('button[type="submit"]');if(btn)btn.disabled=true;try{await req('/api/tenant/membership-plans',{method:'POST',body:JSON.stringify(payload)});e.currentTarget.reset();e.currentTarget.elements.priceVnd.value='19900';e.currentTarget.elements.durationDays.value='30';await loadTenantMemberships();alert('Đã tạo gói hội viên.')}catch(err){alert(err.message)}finally{if(btn)btn.disabled=false}});$('#refreshMembershipPlans')?.addEventListener('click',loadTenantMemberships);
